import { MeshStandardNodeMaterial, Mesh } from 'three/webgpu';
import { texture, uv, vec3, mix, smoothstep } from 'three/tsl';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  const timelines = [];
  const toDispose = [];

  // Load textures and initialize scene
  Promise.all([
    ctx.textureLoader.loadTexture(config.imageUrl),
    ctx.textureLoader.loadTexture(config.depthMapUrl),
  ]).then(([imageTex, depthTex]) => {
    setupPlateAndCaption(imageTex, depthTex);
  });

  function setupPlateAndCaption(imageTex, depthTex) {
    imageTex.colorSpace = 'srgb';
    depthTex.colorSpace = 'linear';
    toDispose.push(imageTex, depthTex);

    // Tessellated plane geometry for displacement
    const geometry = new THREE.PlaneGeometry(4.0, 2.5, 64, 64);
    toDispose.push(geometry);

    // TSL shader nodes
    const imageTexNode = texture(imageTex);
    const depthTexNode = texture(depthTex);
    const uv0 = uv();

    // Sample depth and displace UVs
    const depthSample = depthTexNode.sample(uv0).r;
    const displacedUV = uv0.add(depthSample.mul(0.18).sub(0.09));

    // Sample image with displacement
    const colorSample = imageTexNode.sample(displacedUV);

    // Filmic grade: blacks lifted to #0d0d12, highlights shouldered to #e8ecf2
    const liftedBlack = vec3(0.051, 0.051, 0.071);
    const shoulderedWhite = vec3(0.910, 0.925, 0.949);

    // Tone curve remapping
    const toneCurved = mix(liftedBlack, shoulderedWhite, smoothstep(vec3(0), vec3(1), colorSample));

    // Midtone contrast +12%
    const contrasted = mix(colorSample, toneCurved, 0.12);

    // Desaturation -8% (keep 92%) with red channel preservation
    const luminance = colorSample.r.mul(0.3).add(colorSample.g.mul(0.59)).add(colorSample.b.mul(0.11));
    const desaturated = mix(luminance, contrasted, 0.92);

    // Red from original contrast, GB from desaturated
    const filmicGraded = vec3(contrasted.r, desaturated.g, desaturated.b);

    // Create material
    const material = new MeshStandardNodeMaterial({
      colorNode: filmicGraded,
      metalness: 0,
      roughness: 0.7,
      transparent: true,
      opacity: 1.0,
    });
    toDispose.push(material);

    // Create plate mesh
    const plateMesh = new Mesh(geometry, material);
    group.add(plateMesh);

    // Plate entrance: fade in over 500ms
    const plateTL = gsap.timeline();
    plateTL.fromTo(
      plateMesh,
      { opacity: 0 },
      { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' }
    );
    timelines.push(plateTL);

    // Setup caption block
    setupCaptionBlock();
  }

  function setupCaptionBlock() {
    const captionGroup = new THREE.Group();
    // Bottom-left position with 0.5-unit padding from plane edges
    // Plane: 4.0w × 2.5h centered at origin → corners at (±2.0, ±1.25)
    // Bottom-left with 0.5 padding: (-1.5, -0.75)
    captionGroup.position.set(-1.5, -0.75, 0.1);
    group.add(captionGroup);

    // Text content with typography specs
    const textItems = [
      { text: 'NOVA ATELIER / GENEVA', role: 'kicker', size: 9 },
      { text: 'Time, Machined.', role: 'headline', size: 34 },
      { text: 'Every case begins as a single billet of 904L steel.', role: 'body', size: 13 },
      { text: 'CALIBRE NA-01 / 72 HOUR RESERVE', role: 'caption', size: 9 },
    ];

    let yOffset = 0;

    for (let i = 0; i < textItems.length; i++) {
      const item = textItems[i];

      // Render text
      const textMesh = ctx.fontAtlas.createText(item.text, {
        fontSize: item.size,
        color: '#e8ecf2',
        align: 'left',
        letterSpacingPx: (item.role === 'kicker' || item.role === 'caption') ? 0.12 * item.size : 0,
      });
      textMesh.position.y = yOffset;
      textMesh.position.z = 0.2;
      captionGroup.add(textMesh);

      // Insert accent hairline after headline
      if (i === 1) {
        const accentGeo = new THREE.PlaneGeometry(0.75, 0.02);
        toDispose.push(accentGeo);

        const accentMat = new MeshStandardNodeMaterial({
          colorNode: vec3(1.0, 0.16, 0.22), // #ff2a38
          metalness: 0,
          roughness: 0,
        });
        accentMat.emissive.setHex(0xff2a38);
        accentMat.emissiveIntensity = 1.8;
        toDispose.push(accentMat);

        const accentBar = new Mesh(accentGeo, accentMat);
        accentBar.position.y = yOffset - 0.25;
        accentBar.position.z = 0.15;
        captionGroup.add(accentBar);

        yOffset -= 0.27; // Spacing + bar height
      } else {
        // 0.25-unit baseline rhythm
        yOffset -= 0.25;
      }
    }

    // Caption block entrance: rise in with delay
    const captionTL = gsap.timeline({ delay: 0.12 });
    captionTL.fromTo(
      captionGroup.position,
      { y: -0.75 + 0.4 },
      { y: -0.75, duration: 0.7, ease: 'cubic-bezier(0.215,0.61,0.355,1)' }
    );
    timelines.push(captionTL);
  }

  // Apply parallax-scroll primitive for depth effect
  const parallaxResult = ctx.primitives['parallax-scroll'](group, { intensity: 0.35 });

  // Cleanup function
  group.userData.cleanup = () => {
    timelines.forEach(tl => tl?.kill?.());
    toDispose.forEach(item => item?.dispose?.());
    parallaxResult?.cleanup?.();
  };

  return group;
}
